import pandas as pd,numpy as np, itertools
from scipy.signal import lfilter
files=['train/A_vref_op1.csv','train/A_amb_op1.csv','train/A_amb_op2.csv','train/A_vref_op3.csv','train/A_fault_op1.csv','train/A_line_op3.csv','train/A_gentrip_op1.csv','train/A_load_op2.csv']
def ld(f):
    d=pd.read_csv(f); return {k:d[c].values for k,c in [('t','time_s'),('P','active_power_pu'),('Q','reactive_power_pu'),('V','voltage_pu'),('th','bus_angle_rad'),('Vs','voltage_setpoint_pu')]}
DS=[ld(f) for f in files]
def lag(u,T,dt):
    al=dt/T; return lfilter([al],[1,-(1-al)],u-u[0])
def feats(D,T1,T2,T3,useth,useom):
    dt=D['t'][1]; V=D['V']; Vs=D['Vs']; P=D['P']; th=D['th']
    cols=[np.ones(len(V)), lag(Vs-Vs[0],T1,dt), lag(V-V[0],T2,dt), lag(P-P[0],T3,dt)]
    if useth: cols.append(th)
    if useom: cols.append((th-lag(th,0.003,dt))/0.003)
    return np.column_stack(cols)
best=None
for T1,T2,T3 in itertools.product([0.05,0.5,2],[0.01,0.1,0.5],[0.01,0.1,0.5]):
  for useth,useom in [(0,0),(1,0),(0,1),(1,1)]:
    A=[feats(D,T1,T2,T3,useth,useom) for D in DS]
    AA=np.vstack(A); yy=np.concatenate([D['Q']-D['Q'][0] for D in DS])
    # note: intercept per file handled by using Q-Q0 and features relative (ones column is per file mean shift)
    c,*_=np.linalg.lstsq(AA,yy,rcond=None); rms=np.sqrt(np.mean((AA@c-yy)**2))
    if best is None or rms<best[0]: best=(rms,T1,T2,T3,useth,useom,c)
print(best[:6],np.round(best[6],4))

import pandas as pd,numpy as np
from scipy.signal import lfilter
from scipy.optimize import least_squares
files=['train/A_vref_op1.csv','train/A_amb_op1.csv','train/A_amb_op2.csv','train/A_vref_op3.csv','train/A_fault_op1.csv','train/A_line_op3.csv','train/A_gentrip_op1.csv','train/A_load_op2.csv']
def ld(f):
    d=pd.read_csv(f); return {k:d[c].values for k,c in [('t','time_s'),('P','active_power_pu'),('Q','reactive_power_pu'),('V','voltage_pu'),('th','bus_angle_rad'),('Vs','voltage_setpoint_pu')]}
DS=[ld(f) for f in files]
def lag(u,T,dt):
    al=dt/T; return lfilter([al],[1,-(1-al)],u-u[0])
def simP(p,D):
    Kp,Tw,Tp,kPs,kPv=p
    dt=D['t'][1]; V=D['V']; Vs=D['Vs']; th=D['th']
    V0=V[0]; dv=Vs-V0
    om=(th-th[0]-lag(th-th[0],Tw,dt))/Tw/(2*np.pi*60)
    return D['P'][0]+lag(-Kp*om+kPs*dv+kPv*(V-V0),Tp,dt)
def resP(p): return np.concatenate([simP(p,D)-D['P'] for D in DS])
